const allRows = $input.all().map(i => i.json);
const cfg = $('Set config').item.json;

// Need at least 2 rows to compare
if (allRows.length < 2) {
  return [{
    json: {
      hasAnomalies: false,
      notEnoughData: true,
      message: 'Not enough data yet. Add at least 2 weeks of KPI data to the KPI Log sheet before this workflow can compare.',
      alertEmail: cfg.alertEmail,
      senderName: cfg.senderName,
      today: cfg.today
    }
  }];
}

// Most recent row = this week, second to last = previous week
const current = allRows[allRows.length - 1];
const previous = allRows[allRows.length - 2];

const threshold = parseFloat(cfg.dropThreshold) || 20;

// Detect all metric columns — skip Week and any row_number columns
const metricKeys = Object.keys(current).filter(k =>
  k !== 'Week' &&
  k !== 'Date' &&
  k !== 'row_number' &&
  !k.startsWith('_')
);

const allChanges = [];
const anomalies = [];

metricKeys.forEach(key => {
  const currentVal = parseFloat(String(current[key]).replace(/[,$%]/g, ''));
  const previousVal = parseFloat(String(previous[key]).replace(/[,$%]/g, ''));

  // Skip non-numeric columns or zero previous values
  if (isNaN(currentVal) || isNaN(previousVal)) return;
  if (previousVal === 0) return;

  const changePct = ((currentVal - previousVal) / previousVal) * 100;
  const isAnomaly = changePct <= -threshold;
  const direction = changePct >= 0 ? 'UP' : 'DOWN';

  const entry = {
    metric: key,
    currentValue: currentVal,
    previousValue: previousVal,
    changePercent: Math.round(changePct * 10) / 10,
    direction,
    isAnomaly
  };

  allChanges.push(entry);
  if (isAnomaly) anomalies.push(entry);
});

// Sort anomalies by severity (worst drop first)
anomalies.sort((a, b) => a.changePercent - b.changePercent);

const currentWeekLabel = current.Week || current.Date || 'Current week';
const previousWeekLabel = previous.Week || previous.Date || 'Previous week';

return [{
  json: {
    hasAnomalies: anomalies.length > 0,
    notEnoughData: false,
    anomalies,
    allChanges,
    anomalyCount: anomalies.length,
    totalMetrics: allChanges.length,
    currentWeekLabel,
    previousWeekLabel,
    dropThreshold: threshold,
    businessContext: cfg.businessContext,
    alertEmail: cfg.alertEmail,
    senderName: cfg.senderName,
    today: cfg.today
  }
}];

const gptOut = $input.first().json.output;
const data = $('Compare the last two weeks').item.json;

if (!gptOut) {
  throw new Error('AI analysis failed. Check your OpenAI credential and try again.');
}

const senderName = data.senderName;
const currentWeek = data.currentWeekLabel;
const previousWeek = data.previousWeekLabel;

// Build full metrics change table
const changesTable = data.allChanges.map(c => {
  const arrow = c.direction === 'UP' ? '+' : '';
  const flag = c.isAnomaly ? '  <-- ALERT' : '';
  return c.metric + ': ' + c.currentValue + ' (was ' + c.previousValue + ') ' + arrow + c.changePercent + '%' + flag;
}).join('\n');

// Build per-anomaly analysis
const anomalySection = (gptOut.anomalyAnalysis || []).map(a => {
  const causes = (a.likelyCauses || []).map((c, i) => '  ' + (i + 1) + '. ' + c).join('\n');
  const actions = (a.immediateActions || []).map((ac, i) => '  ' + (i + 1) + '. ' + ac).join('\n');
  return (
    a.metric + ' — dropped ' + Math.abs(data.anomalies.find(x => x.metric === a.metric)?.changePercent || 0) + '%\n' +
    'Likely causes:\n' + causes + '\n' +
    'Immediate actions:\n' + actions
  );
}).join('\n\n');

// Build positives section if any
const positives = (gptOut.positiveHighlights || []);
const positivesSection = positives.length > 0
  ? positives.map((p, i) => (i + 1) + '. ' + p).join('\n')
  : 'No notable improvements this week.';

const emailBody =
  'Hello ' + senderName + ',\n\n' +
  gptOut.executiveSummary + '\n\n' +
  '============================================================\n' +
  'ALL METRICS — WEEK OF ' + currentWeek + ' vs ' + previousWeek + '\n' +
  '============================================================\n\n' +
  changesTable + '\n\n' +
  '============================================================\n' +
  'ANOMALY ANALYSIS — METRICS THAT DROPPED ' + data.dropThreshold + '% OR MORE\n' +
  '============================================================\n\n' +
  anomalySection + '\n\n' +
  '============================================================\n' +
  'WHAT IS WORKING\n' +
  '============================================================\n\n' +
  positivesSection + '\n\n' +
  '============================================================\n' +
  'WEEKLY OUTLOOK\n' +
  '============================================================\n\n' +
  gptOut.weeklyOutlook + '\n\n' +
  '============================================================\n' +
  'PRIORITY ACTION THIS WEEK\n' +
  '============================================================\n\n' +
  gptOut.priorityAction + '\n\n' +
  'Full KPI history is in your Google Sheets KPI Log tab.\n\n' +
  'Best regards,\n' + senderName;

const subjectMetrics = data.anomalies.slice(0, 2).map(a => a.metric + ' ' + a.changePercent + '%').join(', ');

return [{
  json: {
    emailSubject: data.anomalyCount + ' KPI Alert: ' + subjectMetrics + (data.anomalyCount > 2 ? ' and more' : '') + ' — ' + currentWeek,
    emailBody,
    alertEmail: data.alertEmail
  }
}];
